;(function(global){"use strict";
const VERSION="0.9.0",CONTRACT="p9-dashboard-v1";
function core(){if(!global.THIEPN_LANGUAGE_READ_MODEL)throw new Error("THIEPN_LANGUAGE_READ_MODEL_REQUIRED");return global.THIEPN_LANGUAGE_READ_MODEL}
function iso(v){return typeof v==="string"&&v&&Number.isFinite(new Date(v).getTime())}
function str(v,n){const s=String(v??"").trim();if(!s)throw new Error("MISSING_"+n);return s}
function validate(value){const issues=[];if(!value||typeof value!=="object")return {ok:false,issues:["dashboard payload must be an object"]};if(value.schema!=="thiepn-language-dashboard")issues.push("unexpected dashboard schema");if(value.schemaVersion!==1)issues.push("unsupported dashboard schema version");if(value.contractVersion!==CONTRACT)issues.push("unexpected dashboard contract version");if(!iso(value.generatedAt))issues.push("generatedAt must be ISO timestamp");if(!Array.isArray(value.enrollments))issues.push("enrollments must be an array");if(!Array.isArray(value.snapshots))issues.push("snapshots must be an array");for(const e of value.enrollments||[]){if(!String(e?.appId??"").trim()||!String(e?.languageId??"").trim())issues.push("invalid enrollment identity");if(typeof e?.visible!=="boolean")issues.push("enrollment.visible must be boolean");if(!iso(e?.connectedAt)||!iso(e?.updatedAt))issues.push("invalid enrollment timestamp")}for(const s of value.snapshots||[]){if(!Number.isInteger(s?.revision)||s.revision<1)issues.push("invalid snapshot revision");if(!iso(s?.storedAt))issues.push("invalid snapshot storedAt");const v=core().validateLanguageReadModel(s?.snapshot);if(!v.ok)issues.push(...v.issues.map(x=>"snapshot: "+x));if(s?.snapshot&&(s.appId!==s.snapshot.appId||s.languageId!==s.snapshot.languageId))issues.push("snapshot identity mismatch")}return {ok:issues.length===0,issues}}
function visible(p){const v=validate(p);if(!v.ok)throw new Error("INVALID_LANGUAGE_DASHBOARD:"+v.issues.join("|"));const set=new Set(p.enrollments.filter(x=>x.visible).map(x=>x.appId+"\0"+x.languageId));return p.snapshots.filter(x=>set.has(x.appId+"\0"+x.languageId)).map(x=>x.snapshot)}
function client(o){const base=str(o?.baseUrl,"BASE_URL").replace(/\/+$/,""),f=o?.fetchImpl||global.fetch;if(typeof f!=="function")throw new Error("FETCH_UNAVAILABLE");if(typeof o?.getAccessToken!=="function")throw new Error("TOKEN_PROVIDER_REQUIRED");async function req(path,init={}){const token=await o.getAccessToken();if(!token)throw new Error("AUTH_REQUIRED");const r=await f(base+path,{...init,headers:{Accept:"application/json",Authorization:"Bearer "+token,...(init.body?{"Content-Type":"application/json"}:{}),...(init.headers||{})}});const p=await r.json().catch(()=>null);if(!r.ok||!p?.ok)throw new Error(String(p?.error?.code||("HTTP_"+r.status)));return p.data}return Object.freeze({publish:async s=>{const v=core().validateLanguageReadModel(s);if(!v.ok)throw new Error("INVALID_LANGUAGE_READ_MODEL:"+v.issues.join("|"));return req("/v1/languages/read-models/"+encodeURIComponent(s.appId),{method:"POST",body:JSON.stringify({snapshot:s})})},load:async()=>{const d=await req("/v1/languages/dashboard");const v=validate(d);if(!v.ok)throw new Error("INVALID_LANGUAGE_DASHBOARD:"+v.issues.join("|"));return d},setVisible:async(a,l,v)=>req("/v1/languages/enrollments/"+encodeURIComponent(str(a,"APP_ID")),{method:"POST",body:JSON.stringify({languageId:str(l,"LANGUAGE_ID"),visible:!!v})})})}
global.THIEPN_LANGUAGE_DASHBOARD=Object.freeze({packageVersion:VERSION,contractVersion:CONTRACT,validateLanguageDashboardPayload:validate,visibleLanguageSnapshots:visible,buildPersistedHubDataPlane:(p,o)=>core().buildHubLanguageDataPlane(visible(p),o),createCoreLanguageDashboardClient:client});
})(globalThis);
